function getDefaultSubjects(userId, department, level) {
	const isHSC = level.startsWith("HSC");
	const compulsory = getCompulsorySubjects(userId, isHSC);
	if (department === "Science") return [...getScienceSubjects(userId, isHSC), ...compulsory];
	else if (department === "Commerce") return [...getCommerceSubjects(userId, isHSC), ...compulsory];
	else return [...getHumanitiesSubjects(userId, isHSC), ...compulsory];
}
