// src/utils/imageUtils.ts
/**
* Processes an uploaded image file by center-cropping it to a square
* and resizing to 256x256px so it is fast, crisp, and safe for localStorage.
*/
function processProfileImage(file) {
	return new Promise((resolve, reject) => {
		if (!file.type.startsWith("image/")) {
			reject(/* @__PURE__ */ new Error("Invalid image file type"));
			return;
		}
		const reader = new FileReader();
		reader.onload = (event) => {
			const img = new Image();
			img.onload = () => {
				try {
					const canvas = document.createElement("canvas");
					const size = 256;
					canvas.width = size;
					canvas.height = size;
					const ctx = canvas.getContext("2d");
					if (!ctx) {
						resolve(event.target?.result);
						return;
					}
					const minDim = Math.min(img.width, img.height);
					const sx = (img.width - minDim) / 2;
					const sy = (img.height - minDim) / 2;
					ctx.drawImage(img, sx, sy, minDim, minDim, 0, 0, size, size);
					resolve(canvas.toDataURL("image/jpeg", .85));
				} catch (err) {
					reject(err);
				}
			};
			img.onerror = () => reject(/* @__PURE__ */ new Error("Failed to load image"));
			img.src = event.target?.result;
		};
		reader.onerror = () => reject(/* @__PURE__ */ new Error("Failed to read file"));
		reader.readAsDataURL(file);
	});
}
